@startuml

class SensorController {
  + username : string
  + password : string
}

class Apartment {
  + address : string
}

class Room {
  + description : string
}

abstract class Sensor {
  + vendorId : int
  + description : string
  + unit : Unit
  + room : Room
}

enum Unit {
  CELSIUS
  WATT
}

class TemperatureSensor {
  + minValue : double
  + maxValue : double
}

class PowerSensor {
  + counterReading : double
}

class SensorValue {
  + timestamp : datetime
  + value : float
}

class Threshold {
  + thresholdValue : float
  + emailAddress : string
}

class EMonitor {}

SensorController "1" *-- "* sensors" Sensor
Apartment "1" *-- "* rooms" Room
Room "1" *-- "*" Sensor
Sensor "1" *-- "* values" SensorValue
Sensor "0..1" -- "1 threshold" Threshold
EMonitor "1" ..|> SensorController

@enduml

